'use strict'

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  // line/col at each index, computed lazily in one pass
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let k = 0; k < n; k++) {
    lines[k] = l
    cols[k] = c
    if (cs[k] === '\n') { l++; c = 1 }
    else if (cs[k] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (k, reason) => { throw new ScanError(lines[k], cols[k], reason) }
  const toks = []
  let i = 0

  // consume digits of a run (with single underscores between digits); returns new index
  const run = (j, ok) => {
    if (!ok(cs[j])) return j
    j++
    for (;;) {
      if (ok(cs[j])) j++
      else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const ch = cs[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { i++; continue }
    if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (ch === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= n) fail(start, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      continue
    }
    const start = i
    const push = (kind, value) => toks.push({ kind, value, line: lines[start], col: cols[start] })
    if (ch === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(start, 'unterminated string')
      push('rawstring', cs.slice(i + 2, j).join(''))
      i = j + 1
      continue
    }
    if (isIdStart(ch)) {
      let j = i + 1
      while (isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      i = j
      continue
    }
    if (isDigit(ch)) {
      let j = i
      let bad = false
      const p = cs[i + 1]
      const pre = ch === '0' && p !== undefined ? p.toLowerCase() : ''
      if (pre === 'x' || pre === 'b' || pre === 'o') {
        const ok = pre === 'x' ? isHex : pre === 'b' ? isBin : isOct
        j = run(i + 2, ok)
        if (j === i + 2) bad = true
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          let k = j + 1
          if (cs[k] === '+' || cs[k] === '-') k++
          if (isDigit(cs[k])) j = run(k, isDigit)
        }
      }
      if (isIdPart(cs[j])) {
        bad = true
        while (isIdPart(cs[j])) j++
      }
      const w = cs.slice(i, j).join('')
      if (bad) fail(start, `invalid number ${w}`)
      push('number', w)
      i = j
      continue
    }
    if (ch === '"') {
      let j = i + 1
      let val = ''
      for (;;) {
        if (j >= n) fail(start, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') fail(j, 'newline in string')
        if (d !== '\\') { val += d; j++; continue }
        const e = cs[j + 1]
        if (e === undefined) fail(start, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (Object.prototype.hasOwnProperty.call(simple, e)) { val += simple[e]; j += 2; continue }
        if (e === 'x') {
          if (isHex(cs[j + 2]) && isHex(cs[j + 3])) {
            val += String.fromCodePoint(parseInt(cs[j + 2] + cs[j + 3], 16))
            j += 4
            continue
          }
          fail(j, 'invalid escape \\x')
        }
        if (e === 'u' && cs[j + 2] === '{') {
          let k = j + 3
          while (isHex(cs[k])) k++
          if (k > j + 3 && cs[k] === '}') {
