            if (hex.length <= 6 && parseInt(hex, 16) <= 0x10ffff) {
              val += String.fromCodePoint(parseInt(hex, 16))
              j = k + 1
              continue
            }
          }
        }
        fail(j, `invalid escape \\${e}`)
      }
      push('string', val)
      i = j
      continue
    }
    const two = ch + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { push('punct', two); i += 2; continue }
    if (PUNCT1.has(ch)) { push('punct', ch); i++; continue }
    fail(i, `unexpected character ${ch}`)
  }
  return toks
}

module.exports = { scan, ScanError }
